 System.Windows.FrameworkElement ActivityRing(double size,double progress,System.Windows.Media.Brush color){var grid=new Grid{Width=size,Height=size};grid.Children.Add(new System.Windows.Shapes.Ellipse{Stroke=color,StrokeThickness=11,Opacity=.18});double r=(size-11)/2,c=size/2,angle=Math.Clamp(progress,0,.99999)*Math.PI*2;var figure=new System.Windows.Media.PathFigure{StartPoint=new Point(c,5.5)};figure.Segments.Add(new System.Windows.Media.ArcSegment(new Point(c+r*Math.Sin(angle),c-r*Math.Cos(angle)),new Size(r,r),0,angle>Math.PI,System.Windows.Media.SweepDirection.Clockwise,true));var geometry=new System.Windows.Media.PathGeometry();geometry.Figures.Add(figure);if(progress>0)grid.Children.Add(new System.Windows.Shapes.Path{Data=geometry,Stroke=color,StrokeThickness=11,StrokeStartLineCap=System.Windows.Media.PenLineCap.Round,StrokeEndLineCap=System.Windows.Media.PenLineCap.Round});return grid;}
 System.Windows.FrameworkElement AppIcon(string path){try{using var icon=System.Drawing.Icon.ExtractAssociatedIcon(path);if(icon!=null)return new Image{Source=System.Windows.Interop.Imaging.CreateBitmapSourceFromHIcon(icon.Handle,Int32Rect.Empty,System.Windows.Media.Imaging.BitmapSizeOptions.FromEmptyOptions()),Width=32,Height=32,HorizontalAlignment=HorizontalAlignment.Left};}catch{}return T("↗",27,Accent);}
 void AddInstalledApp(){var list=new ListBox{Height=320,DisplayMemberPath="Key"};var apps=new List<KeyValuePair<string,string>>();var type=Type.GetTypeFromProgID("Shell.Application");if(type==null)throw new Exception("Windows app list unavailable.");dynamic shellApp=Activator.CreateInstance(type)!;dynamic folder=shellApp.NameSpace("shell:AppsFolder");foreach(dynamic item in folder.Items()){string name=item.Name;string path=item.Path;if(!string.IsNullOrWhiteSpace(path))apps.Add(new(name,path.Contains("!")?"shell:AppsFolder\\"+path:path));}list.ItemsSource=apps.OrderBy(x=>x.Key).ToList();var search=Input("","Search installed apps");search.TextChanged+=(_,_)=>list.ItemsSource=apps.Where(x=>x.Key.Contains(search.Text,StringComparison.OrdinalIgnoreCase)).OrderBy(x=>x.Key).ToList();ShowDialog("Add application",Col(search,list),()=>{if(list.SelectedItem is not KeyValuePair<string,string> chosen)throw new Exception("Select an application.");if(!D.Shelf.Contains(chosen.Value))D.Shelf.Add(chosen.Value);Save();RenderTab();});}
 string ConnectedWifi(){var m=Regex.Match(wifiDetails,@"(?m)^\s*SSID\s*:\s*(.+)$");return m.Success?m.Groups[1].Value.Trim():"Not connected";}
 string BluetoothSummary()=>devices.Any(x=>x.State=="Connected")?string.Join(", ",devices.Where(x=>x.State=="Connected").Select(x=>x.Name)):"No connected device";
 bool notificationBusy;
 async Task RefreshSystemNotifications(){if(notificationBusy)return;notificationBusy=true;try{var result=await Native.Broker("notifications");foreach(var item in Elements(result)){string id="Windows · "+item.GetProperty("id").GetString();var title=item.GetProperty("title").GetString()??"Notification";var detail=item.GetProperty("detail").GetString()??"";if(!D.SeenWindowsNotices.Contains(id)){D.SeenWindowsNotices.Add(id);D.Notices.Insert(0,new Notice{Title=title,Detail=detail});}}D.Notices=D.Notices.Take(200).ToList();Save();if(tab=="Notifications"&&expanded)RenderTab();}catch(Exception ex){S.SystemNotifications=false;Save();Notify("Windows notification access unavailable",ex.Message+" Enable access in Windows privacy settings, then try again.",false);}finally{notificationBusy=false;}}
 readonly List<(string Role,string Text)> chat=new();string chatDraft="",chatError="";bool chatBusy;
 void AiChat(){var panel=new DockPanel();body.Children.Add(panel);var tools=Row(Btn("New chat",()=>{chat.Clear();chatError="";RenderTab();}),Btn("AI settings",OpenSettings),T(S.AiModel,12,Muted));DockPanel.SetDock(tools,Dock.Top);panel.Children.Add(tools);var composer=new Grid{Margin=new Thickness(0,14,0,0)};composer.ColumnDefinitions.Add(new());composer.ColumnDefinitions.Add(new(){Width=GridLength.Auto});var input=Input(chatDraft,"Message… Enter to send, Shift+Enter for a new line",true);input.MaxHeight=90;input.TextChanged+=(_,_)=>chatDraft=input.Text;input.KeyDown+=async(_,e)=>{if(e.Key==Key.Enter&&(Keyboard.Modifiers&ModifierKeys.Shift)==0){e.Handled=true;await SendChat();}};Put(composer,input,0);var send=Primary(chatBusy?"Waiting…":"↑ Send",async()=>await SendChat());send.IsEnabled=!chatBusy;Put(composer,send,1);DockPanel.SetDock(composer,Dock.Bottom);panel.Children.Add(composer);var messages=Col();if(chat.Count==0){Gap(messages,50);messages.Children.Add(T("A little help, right here.",28,Fg,true));Gap(messages);messages.Children.Add(T("Chat with your Ollama model. Choose a server and model in Settings → AI Chat.",14,Muted));}foreach(var message in chat){var item=Col(T(message.Role=="user"?"YOU":"ASSISTANT",11,Muted,true),T(message.Text,15));var c=Card(item,14);c.Margin=new Thickness(message.Role=="user"?65:0,10,message.Role=="user"?0:65,0);messages.Children.Add(c);}if(chatError!="")messages.Children.Add(T(chatError,13,Brush("#FF9E7D")));var scroll=Scroll(messages);panel.Children.Add(scroll);scroll.Loaded+=(_,_)=>scroll.ScrollToEnd();}
 async Task SendChat(){if(chatBusy||string.IsNullOrWhiteSpace(chatDraft))return;var text=chatDraft.Trim();chat.Add(("user",text));chatDraft="";chatBusy=true;chatError="";RenderTab();try{if(!Uri.TryCreate(S.AiEndpoint,UriKind.Absolute,out var uri)||uri.Scheme is not ("http" or "https"))throw new Exception("Set a valid HTTP endpoint in AI settings.");var payload=JsonSerializer.Serialize(new{model=S.AiModel,stream=false,messages=chat.Select(x=>new{role=x.Role,content=x.Text})});using var client=new HttpClient{Timeout=TimeSpan.FromMinutes(2)};using var response=await client.PostAsync(uri,new StringContent(payload,Encoding.UTF8,"application/json"));response.EnsureSuccessStatusCode();using var doc=JsonDocument.Parse(await response.Content.ReadAsStringAsync());chat.Add(("assistant",doc.RootElement.GetProperty("message").GetProperty("content").GetString()??""));}catch(Exception ex){chatError="Could not reach the model: "+ex.Message;chat.RemoveAt(chat.Count-1);chatDraft=text;}finally{chatBusy=false;if(tab=="AI Chat"&&expanded)RenderTab();}}
